mapper.select:
select id, chat_type, chat_name, group_id, create_time, update_time
from te_chat
where id = #{id}

select c.id, c.chat_type, c.chat_name, c.group_id, c.create_time, c.update_time
from te_chat c
join te_chat_member m1 on m1.chat_id = c.id and m1.user_id = #{param1}
join te_chat_member m2 on m2.chat_id = c.id and m2.user_id = #{param2}
where c.chat_type = 1
limit 1
